/* Generated synthetic pilot. Native gzip decoding; no network or CDN. */
window.CLOSED_LOOP_READY = (async () => {
  if (typeof DecompressionStream === 'undefined') throw Error('Browser requires DecompressionStream support.');
  const bytes = Uint8Array.from(atob(''), c => c.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  return JSON.parse(await new Response(stream).text());
})();
